var Cache = require("@taf/taf-dcache-helper");
var cacheHelper1 = new Cache({
    DCacheServerTarget: "DCache.QBProxyServer.ProxyObj",
    moduleName: "QBUserInfo",
    allowProxy: true
});


var cacheHelper2 = new Cache({
    DCacheServerTarget: "DCache.QBProxyServer.ProxyObj",
    moduleName: "QBUserScore",
    allowProxy: true
});


function cacheSucCallback1(ret)
{
    console.log("cacheSucCallback1: ", ret);
}

function cacheErrCallback1(ret)
{
    console.log("cacheErrCallback1: ", ret);
}

function cacheSucCallback2(ret)
{
    console.log("cacheSucCallback2: ", ret);
}

function cacheErrCallback2(ret)
{
    console.log("cacheErrCallback2: ", ret);
}

cacheHelper1.setString("author", "m1", cacheSucCallback1, cacheSucCallback1);
cacheHelper2.setString("author", "m2", cacheSucCallback2, cacheErrCallback2);
setTimeout(function(){
    cacheHelper1.getString("author", cacheSucCallback1, cacheErrCallback1);
    cacheHelper2.getString("author", cacheSucCallback2, cacheErrCallback2);
}, 1000);